const __inputRaw = workflowContext.actions['AI_Recovery_Agent'].outputs.body;
const __inputValues = Array.isArray(__inputRaw) ? __inputRaw : [__inputRaw];
const items = __inputValues.map(value =>
  value && typeof value === 'object' && 'json' in value ? value : { json: value }
);
const __unwrap = value => {
  if (Array.isArray(value)) {
    return value.map(item =>
      item && typeof item === 'object' && 'json' in item ? item.json : item
    );
  }
  return value && typeof value === 'object' && 'json' in value ? value.json : value;
};
const __node = name => {
  const output = workflowContext.actions[name]?.outputs;
  const raw = output && typeof output === 'object' && 'body' in output
    ? output.body
    : output;
  const values = Array.isArray(raw) ? raw : [raw];
  const wrapped = values.map(value =>
    value && typeof value === 'object' && 'json' in value ? value : { json: value }
  );
  return {
    item: wrapped[0],
    first: () => wrapped[0],
    last: () => wrapped[wrapped.length - 1],
    all: () => wrapped
  };
};

const $json = items[0]?.json ?? {};
const $input = {
  item: items[0],
  first: () => items[0],
  last: () => items[items.length - 1],
  all: () => items
};
const __result = (() => {
const rawOutput = $input.first().json.output || $input.first().json.text || $input.first().json.content || '';

let parsed;
try {
  const cleaned = rawOutput
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    escalation_level: 1,
    subject: 'Invoice Payment Reminder - Action Required',
    email_body: rawOutput || 'Please review your outstanding invoice.',
    payment_plans: [],
    escalation_action: 'none',
    summary: 'Standard reminder sent (parse fallback)'
  };
}

const sourceItem = __node('Read_Overdue_Invoices').item.json;

return [{
  json: {
    ...parsed,
    invoice_number: sourceItem['Invoice'],
    client_name: sourceItem['Client'],
    client_email: sourceItem['Email'],
    amount_due: sourceItem['Amount'],
    days_overdue: sourceItem['Days Overdue'],
    payment_plans_text: Array.isArray(parsed.payment_plans) ? parsed.payment_plans.join(' | ') : ''
  }
}];
})();
return { body: __unwrap(__result) };
